import java.util.Arrays;
import java.util.List;
import java.util.Optional;

public class Main {
    public static void main(String[] args) {
        List<String> antrean = Arrays.asList("Budi", "Sari", "Andi", "Siti", "Dewi");

        boolean adaAwalanS = antrean.stream().anyMatch(n -> n.startsWith("S"));
        boolean semuaEmpat = antrean.stream().allMatch(n -> n.length() == 4);
        boolean tidakAdaZ = antrean.stream().noneMatch(n -> n.startsWith("Z"));
        System.out.println(adaAwalanS + " " + semuaEmpat + " " + tidakAdaZ);

        Optional<String> pertamaS = antrean.stream()
                .filter(n -> n.startsWith("S"))
                .findFirst();
        System.out.println(pertamaS.get());

        Optional<String> awalanX = antrean.stream()
                .filter(n -> n.startsWith("X"))
                .findFirst();
        System.out.println(awalanX.orElse("tidak ada"));
    }
}

