import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> suhu = Arrays.asList(29, 31, 35, 28, 33);
        System.out.println(suhu.stream().anyMatch(s -> s > 34));
        System.out.println(suhu.stream().allMatch(s -> s > 25));
        int pertama = suhu.stream()
                .filter(s -> s > 30)
                .findFirst()
                .orElse(0);
        System.out.println(pertama);
    }
}

